// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EmergencyOracleFactory} from "../src/EmergencyOracleFactory.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EmergencyOracleFactory c;

    function setUp() public {
        c = new EmergencyOracleFactory();
    }

    function _run(bool setAdmin) internal {
        bool adminBefore;
        try c.isAdmin(address(this)) returns (bool __r) { adminBefore = __r; } catch { return; }
        bool reverted;
        try c.newEmergencyOracle("test") {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted == !adminBefore);
    }

    function testFuzz_run(bool setAdmin) public {
        _run(setAdmin);
    }

    receive() external payable {}
}
